import inspect
import functools
from asyncio import iscoroutinefunction
from dataclasses import dataclass, field
from functools import cached_property
from typing import Any, Callable

@dataclass
class Dependant:
    call: Any = None

    @cached_property
    def _unwrapped_call(self) -> Any:
        if self.call is None:
            return self.call
        return inspect.unwrap(self.call)

    @cached_property
    def is_coroutine_callable(self) -> bool:
        if inspect.isroutine(self._unwrapped_call):
            return iscoroutinefunction(self._unwrapped_call)
        if inspect.isclass(self._unwrapped_call):
            return False
        dunder_call = getattr(self._unwrapped_call, "__call__", None)
        return iscoroutinefunction(dunder_call)

class AsyncCallable:
    async def __call__(self):
        pass

async def async_func():
    pass

def sync_func():
    pass

# Test cases
cases = [
    ("async function", async_func, True),
    ("sync function", sync_func, False),
    ("async callable class instance", AsyncCallable(), True),
    ("sync callable class instance", lambda: None, False), # lambda is routine
    ("partial async function", functools.partial(async_func), True),
    ("partial async callable class instance", functools.partial(AsyncCallable(),), True),
]

print(f"{'Case':<40} | {'Expected':<10} | {'Actual':<10} | {'Result'}")
print("-" * 75)

for name, call, expected in cases:
    dep = Dependant(call=call)
    actual = dep.is_coroutine_callable
    print(f"{name:<40} | {str(expected):<10} | {str(actual):<10} | {'OK' if actual == expected else 'FAIL'}")

